const prep = $('Code - parse report1').first().json;
const saved = $('Postgres - save monitor result1').first().json;
const recipients = prep.recipients ?? [];
const api_key = prep.api_key ?? null;

function formatGmt8(value) {
  if (!value) return 'unknown time';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value);
  return d.toLocaleString('en-MY', {
    timeZone: 'Asia/Kuala_Lumpur',
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }) + ' (GMT+8)';
}

if (!api_key) {
  return [{ json: { skipped: true, reason: 'No paired WhatsApp api_key for owner — connect device first', owner_email: prep.owner_email } }];
}
if (!recipients.length) {
  return [{ json: { skipped: true, reason: 'No to_receipient_phone_ids in monitor config' } }];
}

function normalizeTo(value) {
  const v = String(value).trim();
  if (!v) return null;
  if (v.includes('@')) return v;
  const digits = v.replace(/\D/g, '');
  return digits ? `${digits}@s.whatsapp.net` : null;
}

const windowLabel = prep.window_label_gmt8
  ?? `${formatGmt8(prep.window_start)} → ${formatGmt8(prep.window_end)}`;

const header = [
  `*📋 ${prep.monitor_name ?? 'ActionNow Report'}*`,
  `*Score:* ${prep.relevance_score}/100`,
  `*Window:* ${windowLabel}`,
  '',
].join('\n');

const body = String(prep.report_whatsapp ?? prep.report_markdown ?? '').trim();
const text = (header + body).slice(0, 4096);

return recipients
  .map((r) => ({
    json: {
      to: normalizeTo(r),
      text,
      api_key,
      owner_email: prep.owner_email,
      monitor_result_id: saved.id,
      monitor_setting_id: prep.id,
    },
  }))
  .filter((x) => x.json.to);

